#!/usr/bin/env bash
# Execute unchanged cases through the existing runner. All cases use this path,
# including singletons. Only stacked jobs need extra, disposable git worktrees.
run_case_stack() {
    local job="$INPUT_RUN_MATRIX_PACKAGE_JSON" root="$GITHUB_WORKSPACE"
    local action_script="${SCRIPT_DIR}/action.sh" count case_json id case_dir checkout
    local overall=0 status output diagnostics
    count=$(printf '%s' "$job" | jq -er '.cases | length | select(. > 0)') || return 1
    # Validate the transport before executing any commands. Setup identity must
    # match each case, even if a malformed matrix bypasses the planner.
    printf '%s' "$job" | jq -e '
        del(.cases, .osIndex, .osCount, .hasMultipleOs, .osShort, .osEmoji) as $setup |
        all(.cases[]; (.id | test("^case-[0-9]+$")) and
          ((.package | del(.features)) == $setup)) and
        ([.cases[].id] | length == (unique | length))' >/dev/null || return 1
    if [[ "$count" -gt 1 ]]; then
        printf '%s' "$job" | jq -e '(.freshRunner != true) and
            ((.ciSteps // "") == "") and ((.dependencies // "") == "") and
            (.gitSubmodules != true)' >/dev/null || return 1
    fi
    local job_temp
    job_temp=$(mktemp -d "${RUNNER_TEMP:-/tmp}/clippier-job.XXXXXX") || return 1
    mkdir -p "$job_temp/receipts" "$job_temp/diagnostics" "$job_temp/coverage"
    # Publish paths before starting; always() upload can expose partial execution.
    {
        echo "case-receipts-path=$job_temp/receipts"
        echo "coverage-path=$job_temp/coverage"
        echo "failure-artifact-path=$job_temp/diagnostics"
        echo "failure-artifact-name=clippier-diagnostics-${GITHUB_JOB_ID:-job}-$(printf '%s' "$job" | md5sum | cut -c1-12)"
    } >> "$GITHUB_OUTPUT"
    while IFS= read -r case_json; do
        id=$(printf '%s' "$case_json" | jq -r .id)
        case_dir="$job_temp/$id"
        mkdir -p "$case_dir"
        checkout="$root"
        status=0
        if [[ "$count" -gt 1 ]]; then
            checkout="$case_dir/checkout"
            GIT_TERMINAL_PROMPT=0 git --no-pager -C "$root" worktree add --detach "$checkout" HEAD || status=$?
            if [[ "$status" -eq 0 && $(printf '%s' "$case_json" | jq -r '.package.gitSubmodules // false') == true ]]; then
                GIT_TERMINAL_PROMPT=0 git --no-pager -C "$checkout" submodule update --init --recursive || status=$?
            fi
        fi
        if [[ "$status" -eq 0 ]]; then
            # A separate process restores shell/env state between cases. RUNNER_TEMP
            # isolates accumulated summaries, diagnostics and reproduction scripts.
            (
                export GITHUB_WORKSPACE="$checkout" RUNNER_TEMP="$case_dir"
                export INPUT_STACK_CASES=false
                export INPUT_RUN_MATRIX_PACKAGE_JSON
                INPUT_RUN_MATRIX_PACKAGE_JSON=$(printf '%s' "$case_json" | jq -c .package)
                export INPUT_RUN_MATRIX_REPORTING_SCOPE="$id"
                export INPUT_RUN_MATRIX_REPORTING=always
                export GITHUB_OUTPUT="$case_dir/outputs"
                export GITHUB_ENV="$case_dir/env" GITHUB_PATH="$case_dir/path"
                # Per-case coverage is generated by the validation suite before
                # its cleanup step, not from the final case's leftover target.
                if [[ "${INPUT_CASE_COVERAGE:-false}" == true ]]; then
                    export INPUT_RUN_MATRIX_TEMPLATE_VARS
                    local template_vars="${INPUT_RUN_MATRIX_TEMPLATE_VARS:-}"
                    [[ -n "$template_vars" ]] || template_vars='{}'
                    INPUT_RUN_MATRIX_TEMPLATE_VARS=$(printf '%s' "$template_vars" | jq -c --arg file "$job_temp/coverage/$id.lcov" '. + {"coverage-output": $file}') || exit 1
                fi
                bash "$action_script" || exit $?
                # A zero exit without any executed run is not a successful case.
                grep -q '^run-total=[1-9][0-9]*$' "$GITHUB_OUTPUT" || exit 1
                if grep -q '^run-success=false$' "$GITHUB_OUTPUT"; then exit 1; fi
            ) || status=$?
        fi
        output="$case_dir/outputs"
        if [[ -f "$output" ]]; then
            diagnostics=$(sed -n 's/^failure-artifact-path=//p' "$output" | tail -1)
            if [[ -n "$diagnostics" && -d "$diagnostics" ]]; then
                mkdir -p "$job_temp/diagnostics/$id"
                cp -R "$diagnostics/." "$job_temp/diagnostics/$id/" || status=1
            fi
        fi
        if [[ "$checkout" != "$root" && -d "$checkout" ]]; then
            # Only this function's newly-created disposable worktree is removed.
            GIT_TERMINAL_PROMPT=0 git --no-pager -C "$root" worktree remove --force "$checkout" || status=1
        fi
        printf '%s' "$case_json" | jq --argjson code "$status" '{case: ., exit_code: $code}' > "$job_temp/receipts/$id.json" || return 1
        [[ "$status" -eq 0 ]] || overall=1
    done < <(printf '%s' "$job" | jq -c '.cases[]')
    return "$overall"
}
